try {
    const d = msg.payload;
    if (!d.unitId || d.temperature === undefined || d.humidity === undefined || !d.compressorStatus || d.energyConsumption === undefined) {
        node.warn('Invalid data: ' + JSON.stringify(d));
        return null;
    }
    msg.sensorData = {
        unitId: d.unitId,
        temperature: parseFloat(d.temperature),
        humidity: parseFloat(d.humidity),
        compressorStatus: d.compressorStatus,
        energyConsumption: parseFloat(d.energyConsumption),
        timestamp: d.timestamp || new Date().toISOString(),
        warehouseId: env.get('WAREHOUSE_ID') || 'local'
    };
    msg.unitId = d.unitId;
    return msg;
} catch(e) {
    node.error('Parse error: ' + e.message, msg);
    return null;
}

const d = msg.sensorData;
const ts = new Date(d.timestamp).getTime() * 1000000;
msg.payload = `sensor_data,unitId=${d.unitId},warehouseId=${d.warehouseId} temperature=${d.temperature},humidity=${d.humidity},compressorStatus="${d.compressorStatus}",energyConsumption=${d.energyConsumption} ${ts}`;
msg.url = 'http://influxdb:8086/api/v2/write?org=smart_cooling&bucket=cold_storage&precision=ns';
msg.method = 'POST';
msg.headers = {'Authorization':'Token smart-cooling-super-secret-token','Content-Type':'text/plain; charset=utf-8'};
return msg;

// Forward to Ditto Sync Agent's HTTP endpoint (faster than ioFog bus)
const d = msg.sensorData;
msg.payload = d;
msg.url = 'http://ditto-sync-agent:8082/sync/sensor';
msg.method = 'POST';
msg.headers = {'Content-Type':'application/json'};
return msg;

const d = msg.sensorData;
const uid = d.unitId;
const alerts = [];

// Try to get adaptive baselines from flow context (set by Flow 2)
const baseline = flow.get('baseline_' + uid) || null;

// Adaptive thresholds (falls back to static if no baseline)
let TEMP_WARN_HIGH, TEMP_CRIT_HIGH, TEMP_WARN_LOW, TEMP_CRIT_LOW;
let HUM_HIGH, HUM_LOW, ENERGY_WARN, ENERGY_CRIT;

if (baseline && baseline.sampleCount >= 50) {
    // Adaptive: mean ± N*stddev
    TEMP_WARN_HIGH  = Math.min(baseline.mean_temp + 2 * baseline.std_temp, 9.0);
    TEMP_CRIT_HIGH  = Math.min(baseline.mean_temp + 3 * baseline.std_temp, 11.0);
    TEMP_WARN_LOW   = Math.max(baseline.mean_temp - 2 * baseline.std_temp, 0.5);
    TEMP_CRIT_LOW   = Math.max(baseline.mean_temp - 3 * baseline.std_temp, -1.0);
    ENERGY_WARN     = Math.min(baseline.mean_energy + 2 * baseline.std_energy, 4.0);
    ENERGY_CRIT     = Math.min(baseline.mean_energy + 3 * baseline.std_energy, 5.0);
    HUM_HIGH        = 80; HUM_LOW = 50;  // humidity bounds stay static
    node.status({fill:'green', shape:'dot', text:`adaptive (n=${baseline.sampleCount})`});
} else {
    // Static fallback
    TEMP_WARN_HIGH = 8.0; TEMP_CRIT_HIGH = 10.0;
    TEMP_WARN_LOW  = 2.0; TEMP_CRIT_LOW  = 0.0;
    HUM_HIGH = 80;        HUM_LOW = 50;
    ENERGY_WARN = 3.0;    ENERGY_CRIT = 4.0;
    node.status({fill:'yellow', shape:'ring', text:'static thresholds'});
}

// Temperature checks
if (d.temperature >= TEMP_CRIT_HIGH)
    alerts.push({unitId:uid, alertType:'temperature_critical_high', severity:'critical', message:`Temperature critically high: ${d.temperature}°C`, value:d.temperature, threshold:TEMP_CRIT_HIGH, timestamp:d.timestamp});
else if (d.temperature >= TEMP_WARN_HIGH)
    alerts.push({unitId:uid, alertType:'temperature_warning_high', severity:'warning', message:`Temperature above normal: ${d.temperature}°C`, value:d.temperature, threshold:TEMP_WARN_HIGH, timestamp:d.timestamp});
else if (d.temperature <= TEMP_CRIT_LOW)
    alerts.push({unitId:uid, alertType:'temperature_critical_low', severity:'critical', message:`Temperature critically low: ${d.temperature}°C`, value:d.temperature, threshold:TEMP_CRIT_LOW, timestamp:d.timestamp});
else if (d.temperature <= TEMP_WARN_LOW)
    alerts.push({unitId:uid, alertType:'temperature_warning_low', severity:'warning', message:`Temperature below normal: ${d.temperature}°C`, value:d.temperature, threshold:TEMP_WARN_LOW, timestamp:d.timestamp});

// Humidity check
if (d.humidity > HUM_HIGH || d.humidity < HUM_LOW)
    alerts.push({unitId:uid, alertType:'humidity_out_of_range', severity:'warning', message:`Humidity out of range: ${d.humidity}%`, value:d.humidity, threshold:d.humidity > HUM_HIGH ? HUM_HIGH : HUM_LOW, timestamp:d.timestamp});

// Energy check
if (d.energyConsumption >= ENERGY_CRIT)
    alerts.push({unitId:uid, alertType:'energy_critical', severity:'critical', message:`Energy critically high: ${d.energyConsumption}kW`, value:d.energyConsumption, threshold:ENERGY_CRIT, timestamp:d.timestamp});
else if (d.energyConsumption >= ENERGY_WARN)
    alerts.push({unitId:uid, alertType:'energy_warning', severity:'warning', message:`Energy elevated: ${d.energyConsumption}kW`, value:d.energyConsumption, threshold:ENERGY_WARN, timestamp:d.timestamp});

if (alerts.length > 0) { msg.alerts = alerts; msg.sensorData = d; return msg; }
return null;

const alerts = msg.alerts || [];
const outputs = [];
for (const a of alerts) { outputs.push({payload:a, topic:`coldstorage/${a.unitId}/alerts`}); }
return [outputs];

const a = msg.payload;
const ts = new Date(a.timestamp).getTime() * 1000000;
msg.payload = `alerts,unitId=${a.unitId},alertType=${a.alertType},severity=${a.severity} message="${a.message}",value=${a.value},threshold=${a.threshold},resolved="false" ${ts}`;
msg.url = 'http://influxdb:8086/api/v2/write?org=smart_cooling&bucket=alerts&precision=ns';
msg.method = 'POST';
msg.headers = {'Authorization':'Token smart-cooling-super-secret-token','Content-Type':'text/plain; charset=utf-8'};
return msg;

const a = msg.payload;
const key = `${a.unitId}_${a.alertType}`;
const last = context.get(key) || 0;
const now = Date.now();
if (now - last < 600000) { node.debug(`Cooldown: ${key}`); return null; }
context.set(key, now);
return msg;

const a = msg.payload;
const icon = a.severity === 'critical' ? '🔴 CRITICAL' : '🟡 WARNING';
const ts = new Date(a.timestamp).toLocaleString('en-IN', {timeZone:'Asia/Kolkata'});
msg.topic = `[Smart Cold Storage] ${icon} - ${a.unitId}: ${a.alertType.replace(/_/g,' ').toUpperCase()}`;
msg.payload = `Smart Cold Storage Alert
==========================================

Severity  : ${icon}
Unit      : ${a.unitId}
Alert Type: ${a.alertType.replace(/_/g,' ')}
Message   : ${a.message}
Value     : ${a.value}
Threshold : ${a.threshold}
Time (IST): ${ts}

==========================================
Action Required:
${a.severity==='critical'?'IMMEDIATE action required. Check the unit and contact maintenance team.':'Monitor the unit closely. Take corrective action if trend continues.'}

-- Smart Cold Storage Monitoring System`;
return msg;

// Publish sensor reading to ioFog message bus for BigQuery Streamer
const iofogEnabled = env.get('IOFOG_BUS_ENABLED') === 'true';
if (!iofogEnabled) return null;

const d = msg.sensorData;
const iofogPayload = {
    type: 'sensor_reading',
    data: d
};
msg.payload = JSON.stringify(iofogPayload);
msg.url = 'http://localhost:54321/v2/messages/new';
msg.method = 'POST';
msg.headers = {'Content-Type':'application/json'};
return msg;

const unitIds = (env.get('UNIT_IDS') || 'CS-01,CS-02,CS-03').split(',').map(u => u.trim());
const msgs = unitIds.map(uid => ({payload: uid, unitId: uid}));
return [msgs];

const uid = msg.unitId;
const fluxQuery = `
from(bucket: "cold_storage")
  |> range(start: -24h)
  |> filter(fn: (r) => r["_measurement"] == "sensor_data")
  |> filter(fn: (r) => r["unitId"] == "${uid}")
  |> filter(fn: (r) => r["_field"] == "temperature" or r["_field"] == "energyConsumption" or r["_field"] == "humidity")
  |> group(columns: ["_field"])
  |> reduce(fn: (r, accumulator) => ({
      sum: accumulator.sum + r._value,
      sum2: accumulator.sum2 + r._value * r._value,
      count: accumulator.count + 1.0
  }), identity: {sum: 0.0, sum2: 0.0, count: 0.0})
  |> map(fn: (r) => ({
      _field: r._field,
      mean: r.sum / r.count,
      std: math.sqrt(x: (r.sum2 / r.count) - (r.sum / r.count) * (r.sum / r.count)),
      count: r.count
  }))
`;
msg.payload = fluxQuery;
msg.url = 'http://influxdb:8086/api/v2/query?org=smart_cooling';
msg.method = 'POST';
msg.headers = {'Authorization':'Token smart-cooling-super-secret-token','Content-Type':'application/vnd.flux','Accept':'application/csv'};
return msg;

const uid = msg.unitId;
const csv = msg.payload || '';
const baseline = {mean_temp:4.0, std_temp:0.5, mean_energy:2.0, std_energy:0.5, mean_humidity:65.0, std_humidity:3.0, sampleCount:0, updatedAt: new Date().toISOString()};

if (typeof csv === 'string' && csv.length > 10) {
    const lines = csv.split('\n').filter(l => l && !l.startsWith('#') && !l.startsWith(',result'));
    for (const line of lines) {
        const cols = line.split(',');
        if (cols.length < 6) continue;
        const field = cols.find(c => ['temperature','energyConsumption','humidity'].includes(c));
        const meanIdx = cols.findIndex(c => c === 'mean');
        const stdIdx  = cols.findIndex(c => c === 'std');
        const cntIdx  = cols.findIndex(c => c === 'count');
        if (!field) continue;
        const mean = parseFloat(cols[meanIdx]);
        const std  = parseFloat(cols[stdIdx])  || 0.1;
        const cnt  = parseFloat(cols[cntIdx])  || 0;
        if (field === 'temperature')       { baseline.mean_temp=mean; baseline.std_temp=Math.max(std,0.1); baseline.sampleCount=cnt; }
        else if (field === 'energyConsumption') { baseline.mean_energy=mean; baseline.std_energy=Math.max(std,0.05); }
        else if (field === 'humidity')     { baseline.mean_humidity=mean; baseline.std_humidity=Math.max(std,1.0); }
    }
}

// Store in flow context — readable by Flow 1 Adaptive Condition Check
flow.set('baseline_' + uid, baseline);
node.status({fill:'green', shape:'dot', text:`${uid} n=${baseline.sampleCount} updated`});
node.log(`Baseline updated: ${uid} mean_temp=${baseline.mean_temp.toFixed(2)} mean_energy=${baseline.mean_energy.toFixed(2)}`);
return null;

// Receive BigQuery ML anomaly scores pushed by BigQuery Streamer
const body = msg.payload || {};
const unitId = body.unitId;
const cloudScore = body.cloudScore;

if (!unitId || cloudScore === undefined) {
    node.warn('Invalid cloud feedback: ' + JSON.stringify(body));
    msg.payload = {status:'error',msg:'invalid payload'};
    return [msg, null];
}

// Update flow context with cloud calibration score
const existing = flow.get('cloud_scores') || {};
existing[unitId] = {
    score: cloudScore,
    riskLevel: body.riskLevel || 'unknown',
    updatedAt: new Date().toISOString()
};
flow.set('cloud_scores', existing);

node.log(`Cloud feedback: ${unitId} cloudScore=${cloudScore} risk=${body.riskLevel}`);

// Forward to predictive maintenance flow via link
const linkMsg = {payload: {unitId, cloudScore, ...body}};

msg.payload = {status:'ok'};
return [msg, linkMsg];

const score = msg.payload || {};
const unitId = score.unitId;

if (!unitId) {
    msg.payload = {status:'error'};
    return [msg, null];
}

// Store edge score in flow context
const scores = flow.get('edge_scores') || {};
scores[unitId] = score;
flow.set('edge_scores', scores);

node.log(`Edge anomaly: ${unitId} score=${score.score} risk=${score.riskLevel}`);

// Forward to Ditto Sync Agent
const dittoMsg = {
    payload: score,
    url: 'http://ditto-sync-agent:8082/sync/anomaly',
    method: 'POST',
    headers: {'Content-Type':'application/json'}
};

msg.payload = {status:'ok'};
return [msg, dittoMsg];

const unitId = msg.unitId || msg.payload.unitId || msg.payload;

// Gather all available signals
const edgeScores   = flow.get('edge_scores')  || {};
const cloudScores  = flow.get('cloud_scores') || {};
const baseline     = flow.get('baseline_' + unitId) || null;

const edgeScore  = edgeScores[unitId]  ? edgeScores[unitId].score  : null;
const cloudScore = cloudScores[unitId] ? cloudScores[unitId].score : null;

// Recent alert frequency (from context — updated by alert handler)
const alertFreq = flow.get('alert_freq_' + unitId) || 0;
const alertScore = Math.min(alertFreq / 5, 1.0);  // 5+ alerts in period = 1.0

// Composite score
let composite = 0;
let weights = 0;
if (edgeScore  !== null) { composite += 0.4 * edgeScore;  weights += 0.4; }
if (cloudScore !== null) { composite += 0.4 * cloudScore; weights += 0.4; }
composite += 0.2 * alertScore; weights += 0.2;

// Normalize if not all signals available
if (weights > 0 && weights < 1.0) composite = composite / weights;
composite = Math.min(Math.max(composite, 0), 1.0);

// Determine priority
const priority = composite >= 0.8 ? 'critical' : composite >= 0.6 ? 'high' : composite >= 0.4 ? 'medium' : 'low';

// Only generate alert if composite score is elevated for 3 consecutive checks
const prevCount = flow.get('pm_elevated_' + unitId) || 0;
let newCount = composite >= 0.6 ? prevCount + 1 : 0;
flow.set('pm_elevated_' + unitId, newCount);

const shouldAlert = newCount >= 3 && composite >= 0.6;

if (shouldAlert) {
    // Reset counter after alerting
    flow.set('pm_elevated_' + unitId, 0);

    const alert = {
        unitId: unitId,
        alertType: 'predictive_maintenance',
        severity: priority === 'critical' ? 'critical' : 'warning',
        message: `Predictive maintenance: composite score ${composite.toFixed(2)} (${priority})`,
        value: composite,
        threshold: 0.6,
        timestamp: new Date().toISOString(),
        details: {
            edgeScore: edgeScore,
            cloudScore: cloudScore,
            alertFrequency: alertFreq,
            compositeScore: composite,
            priority: priority
        }
    };

    node.warn(`Predictive maintenance alert: ${unitId} composite=${composite.toFixed(2)}`);
    return {payload: alert, topic: `coldstorage/${unitId}/alerts`, unitId: unitId};
}

return null;

const a = msg.payload;
msg.payload = {
    features: {
        maintenance: {
            properties: {
                score: Math.round(a.value * 100),
                recommendation: a.message,
                priority: a.details.priority,
                lastCalculated: a.timestamp
            }
        }
    }
};
msg.url = `http://ditto-sync-agent:8082/sync/sensor`;
msg.method = 'POST';
msg.headers = {'Content-Type':'application/json'};
return msg;

const a = msg.payload;
const key = 'pm_email_' + a.unitId;
const last = context.get(key) || 0;
if (Date.now() - last < 1800000) return null;
context.set(key, Date.now());
return msg;

const a = msg.payload;
const ts = new Date(a.timestamp).toLocaleString('en-IN', {timeZone:'Asia/Kolkata'});
msg.topic = `[Smart Cold Storage] ⚠️ PREDICTIVE MAINTENANCE — ${a.unitId}`;
msg.payload = `Predictive Maintenance Alert
==========================================

Unit      : ${a.unitId}
Risk Level: ${a.details.priority.toUpperCase()}
Score     : ${(a.value*100).toFixed(0)}/100

Signals:
  Edge Anomaly Score : ${a.details.edgeScore !== null ? (a.details.edgeScore*100).toFixed(0) : 'N/A'}/100
  Cloud ML Score     : ${a.details.cloudScore !== null ? (a.details.cloudScore*100).toFixed(0) : 'N/A'}/100
  Alert Frequency    : ${a.details.alertFrequency} alerts

Time (IST): ${ts}
==========================================
Recommendation:
Schedule equipment inspection for ${a.unitId}.
Multiple signals indicate developing problem.

-- Smart Cold Storage Predictive Maintenance`;
return msg;
